-- Mensaje 131 (3-nov-2026): cuándo el dolor ya está contado (decisión de Emilio).
-- Cerebro v16 → v17 (un párrafo nuevo en la Escalera de Capas) y la prueba de discovery.escalera_capas.
-- Protegido: solo cambia si el Cerebro vigente es el v16 con el texto esperado y la regla tiene su texto de hoy.
-- Correrlo dos veces no cambia nada.
DO $c$ DECLARE v int; BEGIN
  IF EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$**Cuándo el dolor ya está contado** `CAMPO`: cuando el cliente ya dijo qué le pasa y qué le cuesta —*"luego no me entrega a tiempo"* y *"pierdo la venta, el cliente se me va"*—, la pista ya está excavada. Te guardas el dolor para la presentación y sigues con lo demás: no hace falta medirlo más.$v$) > 0) THEN RAISE NOTICE 'El Cerebro ya tiene el cambio del 131.'; RETURN; END IF;
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF v <> 16 THEN RAISE EXCEPTION 'se esperaba el Cerebro v16 y está el v%', v; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND is_active AND strpos(body, $v$Una pregunta de sí o no suelta no está mal. Está mal cuando todas son de sí o no y el cliente deja de contar.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado de la pregunta cerrada en la capa 3'; END IF;
  INSERT INTO public.doctrina (version, section_key, order_index, title, body, is_active, created_by)
  SELECT v + 1, section_key, order_index, title,
         replace(body, $v$Una pregunta de sí o no suelta no está mal. Está mal cuando todas son de sí o no y el cliente deja de contar.$v$, $v$Una pregunta de sí o no suelta no está mal. Está mal cuando todas son de sí o no y el cliente deja de contar.

**Cuándo el dolor ya está contado** `CAMPO`: cuando el cliente ya dijo qué le pasa y qué le cuesta —*"luego no me entrega a tiempo"* y *"pierdo la venta, el cliente se me va"*—, la pista ya está excavada. Te guardas el dolor para la presentación y sigues con lo demás: no hace falta medirlo más.$v$),
         true, created_by
  FROM public.doctrina WHERE version = v AND is_active;
  UPDATE public.doctrina SET is_active = false WHERE is_active AND version = v;
END $c$;

UPDATE public.reglas SET resumen = $v$La escalera de capas: capa 1 los hechos, capa 2 la puerta (el cliente suelta una pista o cierra con un «bien»), capa 3 el dolor, que solo se abre si recoges la pista y profundizas. LA PRUEBA: ¿el vendedor pasó de los hechos a preguntas que abren la puerta y, cuando apareció una pista (el «aunque», el «a veces», el «lo único es que»), se quedó en ella y la excavó hasta que el cliente contó el dolor? No se cuentan territorios: si el dolor sale en el primero, se excava ahí y cumple. Devolverle el dolor con sus palabras no se pide aquí: se puede quedar callado y seguir. El dolor ya está contado cuando el cliente dijo qué le pasa y qué le cuesta (pierde la venta, se le va el cliente, compra más caro, se le va el margen): ahí la pista ya está excavada, y lo que el vendedor pregunte después no la deshace. Si después hace una pregunta mal elegida —por ejemplo, algo que el cliente ya le contestó—, eso no cuenta contra esta regla. Si nunca apareció una pista, ¿por lo menos subió de los hechos a preguntas de capa 2? Entonces cumple lo que se podía.$v$, updated_at = now()
WHERE id = 'discovery.escalera_capas' AND resumen = $v$La escalera de capas: capa 1 los hechos, capa 2 la puerta (el cliente suelta una pista o cierra con un «bien»), capa 3 el dolor, que solo se abre si recoges la pista y profundizas. LA PRUEBA: ¿el vendedor pasó de los hechos a preguntas que abren la puerta y, cuando apareció una pista (el «aunque», el «a veces», el «lo único es que»), se quedó en ella y la excavó hasta que el cliente contó el dolor? No se cuentan territorios: si el dolor sale en el primero, se excava ahí y cumple. Devolverle el dolor con sus palabras no se pide aquí: se puede quedar callado y seguir. Si nunca apareció una pista, ¿por lo menos subió de los hechos a preguntas de capa 2? Entonces cumple lo que se podía.$v$;

DO $chk$ BEGIN
  IF (SELECT max(version) FROM public.doctrina WHERE is_active) <> 17 THEN RAISE EXCEPTION 'el Cerebro no quedó en v17'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$**Cuándo el dolor ya está contado** `CAMPO`: cuando el cliente ya dijo qué le pasa y qué le cuesta —*"luego no me entrega a tiempo"* y *"pierdo la venta, el cliente se me va"*—, la pista ya está excavada. Te guardas el dolor para la presentación y sigues con lo demás: no hace falta medirlo más.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el párrafo nuevo no quedó en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.escalera_capas') IS DISTINCT FROM $v$La escalera de capas: capa 1 los hechos, capa 2 la puerta (el cliente suelta una pista o cierra con un «bien»), capa 3 el dolor, que solo se abre si recoges la pista y profundizas. LA PRUEBA: ¿el vendedor pasó de los hechos a preguntas que abren la puerta y, cuando apareció una pista (el «aunque», el «a veces», el «lo único es que»), se quedó en ella y la excavó hasta que el cliente contó el dolor? No se cuentan territorios: si el dolor sale en el primero, se excava ahí y cumple. Devolverle el dolor con sus palabras no se pide aquí: se puede quedar callado y seguir. El dolor ya está contado cuando el cliente dijo qué le pasa y qué le cuesta (pierde la venta, se le va el cliente, compra más caro, se le va el margen): ahí la pista ya está excavada, y lo que el vendedor pregunte después no la deshace. Si después hace una pregunta mal elegida —por ejemplo, algo que el cliente ya le contestó—, eso no cuenta contra esta regla. Si nunca apareció una pista, ¿por lo menos subió de los hechos a preguntas de capa 2? Entonces cumple lo que se podía.$v$ THEN RAISE EXCEPTION 'la regla discovery.escalera_capas no quedó'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$Solo se abre si recoges la pista y profundizas con preguntas abiertas$v$) > 0) < 1 THEN RAISE EXCEPTION 'la cita de la regla ya no está en el Cerebro'; END IF;
END $chk$;
